function assetName(symbol) {
  if (symbol === "BTC") return "Bitcoin";
  if (symbol === "ETH") return "Ethereum";
  if (symbol === "SOL") return "Solana";
  if (symbol === "BNB") return "BNB";
  if (symbol === "TRX") return "TRON";
  if (symbol === "USDC") return "USD Coin";
  return "Tether USD";
}

