  imgTint("assets/native-ui/info-icon.svg", 337, 1208, 42, 42, MUTED);
  drawNetworkIcon(840, 1215, state.sendNetwork, 42);
  text(`${money(feeUsd)} $`, 992, 1226, 38, TEXT, "right", 600);
