function spark(x, y, width, color) {
  ctx.strokeStyle = color;
  ctx.lineWidth = 7;
  ctx.lineCap = "round";
  ctx.beginPath();
  const pts = [0.65, 0.75, 0.3, 0.15, 0.22, 0.1, 0.36, 0.42];
  pts.forEach((p, i) => {
    const px = x + (width * i) / (pts.length - 1);
    const py = y + p * 70;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  });
  ctx.stroke();
}

